import os
from urllib.parse import urlencode

import msal
import requests


def build_authorization_url(
    redirect_uri: str,
    scopes=None,
    state: str | None = None,
    nonce: str | None = None,
):
    tenant_id = os.environ["AZURE_TENANT_ID"]
    client_id = os.environ["AZURE_CLIENT_ID"]
    authority = f"https://login.microsoftonline.com/{tenant_id}/v2.0"

    app = msal.ConfidentialClientApplication(
        client_id=client_id,
        authority=authority,
        client_credential=os.environ.get("AZURE_CLIENT_SECRET"),
    )

    auth_params = {
        "redirect_uri": redirect_uri,
        "scopes": scopes or ["openid", "profile", "email", "offline_access"],
    }
    if state:
        auth_params["state"] = state
    if nonce:
        auth_params["nonce"] = nonce

    return app.get_authorization_request_url(**auth_params)


def exchange_authorization_code(code: str, redirect_uri: str):
    tenant_id = os.environ["AZURE_TENANT_ID"]
    client_id = os.environ["AZURE_CLIENT_ID"]
    authority = f"https://login.microsoftonline.com/{tenant_id}/v2.0"

    app = msal.ConfidentialClientApplication(
        client_id=client_id,
        authority=authority,
        client_credential=os.environ.get("AZURE_CLIENT_SECRET"),
    )

    result = app.acquire_token_by_authorization_code(
        code,
        scopes=["openid", "profile", "email", "offline_access"],
        redirect_uri=redirect_uri,
    )
    return result


def fetch_userinfo(access_token: str):
    resp = requests.get(
        "https://graph.microsoft.com/oidc/userinfo",
        headers={"Authorization": f"Bearer {access_token}"},
        timeout=30,
    )
    resp.raise_for_status()
    return resp.json()


def start_login_flow(redirect_uri: str, code: str | None = None, state: str | None = None):
    if code is None:
        return {
            "authorization_url": build_authorization_url(redirect_uri=redirect_uri, state=state),
        }

    token_result = exchange_authorization_code(code=code, redirect_uri=redirect_uri)
    if "access_token" not in token_result:
        return token_result

    userinfo = fetch_userinfo(token_result["access_token"])
    return {"token": token_result, "userinfo": userinfo}
